n = int(input().strip())
x = int(input().strip())

# The swaps repeat every 6 moves.
n_mod = n % 6

pos = x
for i in range(n_mod, 0, -1):
    if i % 2 == 1:
        # odd move: swap 0 and 1
        if pos == 0:
            pos = 1
        elif pos == 1:
            pos = 0
    else:
        # even move: swap 1 and 2
        if pos == 1:
            pos = 2
        elif pos == 2:
            pos = 1

print(pos)
